import { CommonTypeInfo, TransactionStatusType } from '@cetus/types/src/common-types'
import { Icon } from '@cetus/ui-kit'
import { HStack, Heading, Image, Spinner } from '@chakra-ui/react'

type ToastTitleProps = {
  status?: TransactionStatusType
  info?: CommonTypeInfo | undefined
}

export function ToastTitle(props: ToastTitleProps) {
  const { status = 'confirmation', info } = props

  //  已提交
  if (status === 'submitted') {
    return (
      <>
        <HStack justify="flex-start" align="flex-start" w="100%" alignItems="start">
          <Spinner w="16px" h="16px" flexShrink={0} color="primary" />
          <TitleText text={`${info?.toastTitleText || 'Transaction in progress'}`} />
        </HStack>
      </>
    )
  }

  // 失败
  if (status === 'rejected') {
    return (
      <HStack justify="flex-start" gap="0px" align="flex-start">
        <Icon xlinkHref="#icon-icon_close" variant="error" />(
        <HStack>
          <TitleText text={info?.toastTitleText || 'Transaction failed'} color="primary_red" />
        </HStack>
        )
      </HStack>
    )
  }

  // 成功
  if (status === 'success') {
    return (
      <>
        <HStack justify="flex-start" align="flex-start">
          {info?.iconUrl ? (
            <Image src={info.iconUrl} h="20px" alt="icon" borderRadius="4px" />
          ) : (
            <Icon xlinkHref="#icon-icon_check" svgFill="primary" />
          )}
          <TitleText text={info?.toastTitleText || 'Transaction Successful'} />
        </HStack>
      </>
    )
  }

  return <></>
}

export function TitleText(props: { text?: string; color?: string }) {
  const { text, color = 'text_caption' } = props
  return (
    <Heading fontSize="14px" lineHeight="20px" fontWeight="400" color={color} whiteSpace={{ base: 'pre-wrap', lg: 'pre-line' }}>
      {text}
    </Heading>
  )
}
